/**
 * runquery-rendering-fixture.ts — the fixture table, its row model, and the saved-query helpers
 * the `runquery-rendering` bundle builds on.
 *
 * The bundle creates one small table, `mjit_render.RenderItem`, with identical rows on SQL Server
 * and PostgreSQL. Every row is generated by {@link BuildRenderItems}, so each check computes the
 * rows it expects in TypeScript from the same model and compares them with what the database
 * returned. That keeps the expected answer independent of the rendering pipeline under test.
 *
 * Identifiers are PascalCase and created quoted on PostgreSQL, so query text written the usual
 * MJ way (`SELECT ID FROM mjit_render.RenderItem`) runs unchanged on both platforms through the
 * PostgreSQL provider's identifier auto-quoting.
 */
import { DatabaseProviderBase, Metadata, RunView } from '@memberjunction/core';
import type { DatabasePlatform, IMetadataProvider, UserInfo } from '@memberjunction/core';
import { QueryEngine } from '@memberjunction/core-entities';
import type {
    MJQueryCategoryEntity,
    MJQueryEntity,
    MJQuerySQLEntity,
    MJSQLDialectEntity
} from '@memberjunction/core-entities';
import { UUIDsEqual } from '@memberjunction/global';
import type { IntegrationCheckContext } from '@memberjunction/testing-integration';

/** Schema that holds the fixture table. Created and dropped by the bundle. */
export const RENDER_SCHEMA = 'mjit_render';

/** The fixture table, schema-qualified, as query text refers to it. */
export const RENDER_TABLE = `${RENDER_SCHEMA}.RenderItem`;

/** Number of rows in the fixture table. */
export const RENDER_ROW_COUNT = 240;

/** One fixture row, in the normalized form checks compare against. */
export interface RenderItem {
    ID: number;
    DisplayName: string;
    Notes: string;
    Category: string;
    /** ISO date, `YYYY-MM-DD`. */
    CreatedOn: string;
    Score: number | null;
    IsActive: boolean;
    ParentID: number | null;
}

/**
 * Text values that stress quoting and pattern matching: an apostrophe, `%`, `_`, `[`, a SQL
 * keyword, non-ASCII text, a semicolon and a line-comment marker. Row `ID` uses entry `ID % 10`.
 */
export const RENDER_NOTES: readonly string[] = [
    'plain text',
    "O'Brien's note",
    '100% sure',
    'under_score',
    '[bracketed]',
    'SELECT',
    'Ünïcödé café',
    'semi;colon',
    'dash -- dash',
    "it's 50%_off [x]"
];

/** Category values; row `ID` uses entry `ID % 4`. */
export const RENDER_CATEGORIES: readonly string[] = ['Alpha', 'Beta', 'Gamma', 'Delta'];

/** Builds the fixture rows. Deterministic: the same call always returns the same rows. */
export function BuildRenderItems(): RenderItem[] {
    const rows: RenderItem[] = [];
    for (let id = 1; id <= RENDER_ROW_COUNT; id++) {
        rows.push({
            ID: id,
            DisplayName: `Item ${String(id).padStart(3, '0')}`,
            Notes: RENDER_NOTES[id % RENDER_NOTES.length],
            Category: RENDER_CATEGORIES[id % RENDER_CATEGORIES.length],
            CreatedOn: isoDateAddDays('2026-01-01', id % 60),
            Score: id % 7 === 0 ? null : (id * 37) % 101,
            IsActive: id % 3 !== 0,
            ParentID: id === 1 ? null : Math.floor(id / 2)
        });
    }
    return rows;
}

function isoDateAddDays(isoDate: string, days: number): string {
    const d = new Date(`${isoDate}T00:00:00Z`);
    d.setUTCDate(d.getUTCDate() + days);
    return d.toISOString().slice(0, 10);
}

/** The context's provider as a database provider, or a clear failure when the bundle runs elsewhere. */
export function RequireDatabaseProvider(provider: IMetadataProvider): DatabaseProviderBase {
    if (!(provider instanceof DatabaseProviderBase)) {
        throw new Error('runquery-rendering needs the server transport: the context provider is not a database provider.');
    }
    return provider;
}

/** The platform the bundle is running against. */
export function RenderPlatform(ctx: IntegrationCheckContext): DatabasePlatform {
    return RequireDatabaseProvider(ctx.Provider).PlatformKey;
}

// ─── Table DDL and data ────────────────────────────────────────────────────────

function columnDefinitions(platform: DatabasePlatform): string {
    const q = (name: string): string => platform === 'postgresql' ? `"${name}"` : name;
    const text = platform === 'postgresql' ? 'VARCHAR' : 'NVARCHAR';
    const bool = platform === 'postgresql' ? 'BOOLEAN' : 'BIT';
    return [
        `${q('ID')} INTEGER NOT NULL PRIMARY KEY`,
        `${q('DisplayName')} ${text}(100) NOT NULL`,
        `${q('Notes')} ${text}(200) NOT NULL`,
        `${q('Category')} ${text}(20) NOT NULL`,
        `${q('CreatedOn')} DATE NOT NULL`,
        `${q('Score')} INTEGER NULL`,
        `${q('IsActive')} ${bool} NOT NULL`,
        `${q('ParentID')} INTEGER NULL`
    ].join(',\n    ');
}

function tableName(platform: DatabasePlatform): string {
    return platform === 'postgresql' ? `"${RENDER_SCHEMA}"."RenderItem"` : `${RENDER_SCHEMA}.RenderItem`;
}

function sqlTextLiteral(value: string, platform: DatabasePlatform): string {
    const escaped = value.replace(/'/g, "''");
    return platform === 'postgresql' ? `'${escaped}'` : `N'${escaped}'`;
}

function rowValues(row: RenderItem, platform: DatabasePlatform): string {
    const bool = platform === 'postgresql' ? (row.IsActive ? 'TRUE' : 'FALSE') : (row.IsActive ? '1' : '0');
    return `(${[
        row.ID,
        sqlTextLiteral(row.DisplayName, platform),
        sqlTextLiteral(row.Notes, platform),
        sqlTextLiteral(row.Category, platform),
        `'${row.CreatedOn}'`,
        row.Score === null ? 'NULL' : String(row.Score),
        bool,
        row.ParentID === null ? 'NULL' : String(row.ParentID)
    ].join(', ')})`;
}

function insertStatements(platform: DatabasePlatform): string[] {
    const rows = BuildRenderItems();
    const columns = ['ID', 'DisplayName', 'Notes', 'Category', 'CreatedOn', 'Score', 'IsActive', 'ParentID']
        .map(c => platform === 'postgresql' ? `"${c}"` : c)
        .join(', ');
    const statements: string[] = [];
    const batchSize = 100;
    for (let i = 0; i < rows.length; i += batchSize) {
        const values = rows.slice(i, i + batchSize).map(r => rowValues(r, platform)).join(',\n');
        statements.push(`INSERT INTO ${tableName(platform)} (${columns}) VALUES\n${values}`);
    }
    return statements;
}

/** Statements that remove the fixture table and schema, whether or not they exist. */
function dropStatements(platform: DatabasePlatform): string[] {
    if (platform === 'postgresql') {
        return [`DROP SCHEMA IF EXISTS "${RENDER_SCHEMA}" CASCADE`];
    }
    return [
        `DROP TABLE IF EXISTS ${RENDER_SCHEMA}.RenderItem`,
        `IF SCHEMA_ID('${RENDER_SCHEMA}') IS NOT NULL EXEC('DROP SCHEMA ${RENDER_SCHEMA}')`
    ];
}

function createStatements(platform: DatabasePlatform): string[] {
    const schema = platform === 'postgresql'
        ? `CREATE SCHEMA "${RENDER_SCHEMA}"`
        : `EXEC('CREATE SCHEMA ${RENDER_SCHEMA}')`;
    return [schema, `CREATE TABLE ${tableName(platform)} (\n    ${columnDefinitions(platform)}\n)`];
}

/** Drops any leftover fixture, then creates the table and loads every row. */
export async function CreateRenderTable(ctx: IntegrationCheckContext): Promise<void> {
    const provider = RequireDatabaseProvider(ctx.Provider);
    const platform = provider.PlatformKey;
    for (const sql of [...dropStatements(platform), ...createStatements(platform), ...insertStatements(platform)]) {
        await provider.ExecuteSQL(sql, undefined, { description: 'runquery-rendering fixture' }, ctx.User);
    }
}

/** Removes the fixture table and schema. Never throws. */
export async function DropRenderTable(ctx: IntegrationCheckContext): Promise<void> {
    try {
        const provider = RequireDatabaseProvider(ctx.Provider);
        for (const sql of dropStatements(provider.PlatformKey)) {
            await provider.ExecuteSQL(sql, undefined, { description: 'runquery-rendering teardown' }, ctx.User);
        }
    } catch (e) {
        console.error(`runquery-rendering teardown warning (table): ${e instanceof Error ? e.message : String(e)}`);
    }
}

// ─── Saved queries ─────────────────────────────────────────────────────────────

/** A saved fixture query to create. */
export interface RenderQueryDefinition {
    /** Unique within the bundle; becomes the query's Name. */
    Name: string;
    /** Base SQL, used on every platform that has no variant below. */
    SQL: string;
    /** Platform SQL variants, saved as `MJ: Query SQLs` rows. */
    Variants?: Partial<Record<DatabasePlatform, string>>;
    /** Whether other queries may compose this one. */
    Reusable?: boolean;
}

/** Everything the bundle created in the database, for lookups and teardown. */
export interface RenderFixtures {
    Category: MJQueryCategoryEntity;
    /** Saved queries by Name, in creation order. */
    Queries: Map<string, MJQueryEntity>;
    /** Platform variant rows, deleted before their queries. */
    Variants: MJQuerySQLEntity[];
}

/** Creates the per-run category that owns every fixture query. */
export async function CreateRenderCategory(user: UserInfo): Promise<MJQueryCategoryEntity> {
    const md = new Metadata(); // global-provider-ok: integration test script — single-provider process by design
    const category = await md.GetEntityObject<MJQueryCategoryEntity>('MJ: Query Categories', user);
    category.Name = `IT Render ${Date.now()}`;
    category.UserID = user.ID;
    if (!await category.Save()) {
        throw new Error(`Fixture category save failed: ${category.LatestResult?.CompleteMessage}`);
    }
    return category;
}

/**
 * Saves one fixture query (and its platform variants) under the fixture category. Queries that
 * compose others must be created after the queries they reference.
 */
export async function CreateRenderQuery(
    fixtures: RenderFixtures,
    definition: RenderQueryDefinition,
    user: UserInfo
): Promise<MJQueryEntity> {
    const md = new Metadata(); // global-provider-ok: integration test script — single-provider process by design
    const query = await md.GetEntityObject<MJQueryEntity>('MJ: Queries', user);
    query.Name = definition.Name;
    query.CategoryID = fixtures.Category.ID;
    query.SQL = definition.SQL;
    query.Status = 'Approved';
    query.Reusable = definition.Reusable ?? false;
    if (!await query.Save()) {
        throw new Error(`Fixture query '${definition.Name}' save failed: ${query.LatestResult?.CompleteMessage}`);
    }
    fixtures.Queries.set(definition.Name, query);
    for (const [platform, sql] of Object.entries(definition.Variants ?? {})) {
        if (sql) {
            fixtures.Variants.push(await createVariant(query, platform, sql, user));
        }
    }
    return query;
}

async function createVariant(query: MJQueryEntity, platformKey: string, sql: string, user: UserInfo): Promise<MJQuerySQLEntity> {
    const dialect = await findDialect(platformKey, user);
    const md = new Metadata(); // global-provider-ok: integration test script — single-provider process by design
    const variant = await md.GetEntityObject<MJQuerySQLEntity>('MJ: Query SQLs', user);
    variant.QueryID = query.ID;
    variant.SQLDialectID = dialect.ID;
    variant.SQL = sql;
    if (!await variant.Save()) {
        throw new Error(`Variant for '${query.Name}' (${platformKey}) save failed: ${variant.LatestResult?.CompleteMessage}`);
    }
    return variant;
}

async function findDialect(platformKey: string, user: UserInfo): Promise<MJSQLDialectEntity> {
    await QueryEngine.Instance.Config(false, user);
    const dialect = QueryEngine.Instance.SQLDialects.find(d => d.PlatformKey === platformKey);
    if (!dialect) {
        throw new Error(`No MJ: SQL Dialects row has PlatformKey '${platformKey}'.`);
    }
    return dialect;
}

/** Refreshes the QueryEngine so saved-query lookups and composition see the fixtures. */
export async function RefreshRenderQueries(user: UserInfo): Promise<void> {
    await QueryEngine.Instance.Config(true, user);
}

/** The fixture category's path as composition tokens and CategoryPath lookups expect it. */
export function RenderCategoryPath(fixtures: RenderFixtures): string {
    const engineCategory = QueryEngine.Instance.Queries.find(q => UUIDsEqual(q.CategoryID, fixtures.Category.ID));
    return engineCategory?.CategoryPath ?? fixtures.Category.Name;
}

/**
 * Deletes every fixture query, newest first so a composing query goes before the queries it
 * references, then the category. Best effort: logs and continues on a failed delete.
 */
export async function DeleteRenderQueries(fixtures: RenderFixtures | undefined, user: UserInfo): Promise<void> {
    if (!fixtures) return;
    for (const variant of fixtures.Variants.reverse()) {
        await deleteOrWarn(variant.Delete(), `variant of ${variant.QueryID}`);
    }
    for (const query of [...fixtures.Queries.values()].reverse()) {
        await deleteOrWarn(query.Delete(), `query '${query.Name}'`);
    }
    await sweepCategoryQueries(fixtures.Category, user);
    await deleteOrWarn(fixtures.Category.Delete(), `category '${fixtures.Category.Name}'`);
}

/** Deletes queries left in the category by a check that created its own. */
async function sweepCategoryQueries(category: MJQueryCategoryEntity, user: UserInfo): Promise<void> {
    const leftovers = await new RunView().RunView<MJQueryEntity>({
        EntityName: 'MJ: Queries',
        ExtraFilter: `CategoryID='${category.ID}'`,
        ResultType: 'entity_object',
        BypassCache: true
    }, user);
    for (const query of leftovers.Results ?? []) {
        await deleteOrWarn(query.Delete(), `leftover query '${query.Name}'`);
    }
}

async function deleteOrWarn(deletion: Promise<boolean>, label: string): Promise<void> {
    try {
        if (!await deletion) {
            console.error(`runquery-rendering teardown warning: delete of ${label} failed`);
        }
    } catch (e) {
        console.error(`runquery-rendering teardown warning (${label}): ${e instanceof Error ? e.message : String(e)}`);
    }
}
